const { DatabaseSync } = require('node:sqlite');
const sqliteVec = require('sqlite-vec');
const db = new DatabaseSync(':memory:', { allowExtension: true });
sqliteVec.load(db);
const { vec_version } = db.prepare('select vec_version() as vec_version').get();
console.log('sqlite-vec loaded OK, version:', vec_version);
db.exec('create virtual table v using vec0(embedding float[4])');
const ins = db.prepare('insert into v(rowid, embedding) values (?, ?)');
ins.run(1n, new Float32Array([0.1, 0.1, 0.1, 0.1]));
ins.run(2n, new Float32Array([0.9, 0.9, 0.9, 0.9]));
const rows = db.prepare('select rowid, distance from v where embedding match ? order by distance limit 2').all(new Float32Array([0.85, 0.9, 0.9, 0.9]));
console.log('KNN query result:', JSON.stringify(rows, (k,v) => typeof v === 'bigint' ? Number(v) : v));
db.close();
"

